(function(){
 'use strict';
 const byId=id=>document.getElementById(id);
 const modal=byId('ky-calc-overlay'), display=byId('kycalc-display'), hint=byId('kycalc-hint');
 let expr='',justEvaluated=false,lastValue='';
 const faDigits=s=>String(s).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]).replace(/\./g,'٫').replace(/\*/g,'×').replace(/\//g,'÷').replace(/-/g,'−');
 function paint(){display.textContent=expr?faDigits(expr):'۰';hint.textContent=justEvaluated?'نتیجهٔ محاسبه':(expr?'در حال واردکردن عبارت':'محاسبه را شروع کن')}
 function openCalc(){modal.hidden=false;modal.classList.add('open');modal.setAttribute('aria-hidden','false');paint();const c=byId('kycalc-close');if(c)c.focus()}
 function closeCalc(){modal.classList.remove('open');modal.hidden=true;modal.setAttribute('aria-hidden','true')}
 function tokenise(input){const out=[];let i=0;while(i<input.length){if(/\s/.test(input[i])){i++;continue}if(/[0-9.]/.test(input[i])){let j=i,dots=0;while(j<input.length&&/[0-9.]/.test(input[j])){if(input[j]==='.')dots++;j++}if(dots>1)throw Error('عدد نامعتبر');const n=input.slice(i,j);if(n==='.')throw Error('عدد نامعتبر');out.push({t:'num',v:Number(n)});i=j;continue}if('+-*/()%'.includes(input[i])){out.push({t:input[i],v:input[i]});i++;continue}throw Error('عبارت نامعتبر')};return out}
 function evaluate(input){const ts=tokenise(input);let i=0,pc=false;function expression(){let v=term();while(ts[i]&&(ts[i].t==='+'||ts[i].t==='-')){let op=ts[i++].t;pc=false;let r=term();if(pc)r=v*r;v=op==='+'?v+r:v-r}return v}function term(){let v=factor();while(ts[i]&&(ts[i].t==='*'||ts[i].t==='/')){let op=ts[i++].t,r=factor();if(op==='/'&&r===0)throw Error('تقسیم بر صفر ممکن نیست');v=op==='*'?v*r:v/r}return v}function factor(){if(ts[i]&&ts[i].t==='+' ){i++;return factor()}if(ts[i]&&ts[i].t==='-'){i++;return -factor()}if(!ts[i])throw Error('عدد را کامل وارد کن');let v;if(ts[i].t==='num'){v=ts[i++].v}else if(ts[i].t==='('){i++;v=expression();if(!ts[i]||ts[i].t!==')')throw Error('پرانتز بسته نشده است');i++}else throw Error('عبارت نامعتبر');while(ts[i]&&ts[i].t==='%'){v=v/100;pc=true;i++}return v}const v=expression();if(i!==ts.length)throw Error('عبارت نامعتبر');if(!Number.isFinite(v))throw Error('نتیجه قابل محاسبه نیست');return Math.round((v+Number.EPSILON)*1e8)/1e8}
 function currentNumberEnd(){const m=expr.match(/(?:^|[+*/(\-])(-?\d*\.?\d*)$/);return m?m[0].length:0}
 function press(type,value){try{
   if(type==='clear'){expr='';justEvaluated=false;lastValue='';hint.textContent='همهٔ ورودی پاک شد';paint();return}
   if(type==='back'){expr=expr.slice(0,-1);justEvaluated=false;paint();return}
   if(type==='digit'){if(justEvaluated)expr='';expr+=value;justEvaluated=false;paint();return}
   if(type==='decimal'){if(justEvaluated)expr='';let tail=expr.split(/[+*/()%-]/).pop();if(!tail.includes('.')){if(!tail)expr+='0';expr+='.'}justEvaluated=false;paint();return}
   if(type==='op'){if(!expr&&value!=='-')return;if(justEvaluated)justEvaluated=false;if(/[+*/-]$/.test(expr))expr=expr.slice(0,-1);expr+=value;paint();return}
   if(type==='percent'){if(!expr)return;let m=expr.match(/(\d+(?:\.\d*)?|\.\d+)$/);if(m&&!expr.endsWith('%'))expr+='%';justEvaluated=false;paint();return}
   if(type==='sign'){if(!expr){expr='-';paint();return}let m=expr.match(/(\d+(?:\.\d*)?|\.\d+)$/);if(m){const token=m[1],start=expr.length-token.length,prefix=expr.slice(0,start);if(prefix.endsWith('-')){const before=prefix.slice(0,-1);if(!before||/[+*/(]$/.test(before)){expr=before+token}else{expr=before+'+'+token}}else if(!prefix||/[+*/(]$/.test(prefix)){expr=prefix+'-'+token}else{expr=prefix+'-'+token}}else if(/[+*/(]$/.test(expr)){expr+='-'}justEvaluated=false;paint();return}
   if(type==='equals'){if(!expr)return;const result=evaluate(expr);lastValue=String(result);expr=lastValue;justEvaluated=true;hint.textContent='نتیجه: '+faDigits(lastValue);paint();return}
  }catch(err){hint.textContent=err&&err.message?err.message:'عبارت را بررسی کن';}
 }
 byId('kycalc-keys').addEventListener('click',e=>{const b=e.target.closest('[data-calc]');if(!b)return;press(b.dataset.calc,b.dataset.value||'')});
 byId('kycalc-close').addEventListener('click',closeCalc);
 modal.addEventListener('click',e=>{if(e.target===modal)closeCalc()});
 document.querySelectorAll('[data-open-calculator]').forEach(b=>b.addEventListener('click',openCalc));
 document.querySelectorAll('[data-open-ledger]').forEach(b=>b.addEventListener('click',()=>{byId('ky-ledger-launch').click();setTimeout(()=>{const tab=document.querySelector('#ky-tabs [data-tab="'+b.dataset.openLedger+'"]');if(tab)tab.click()},120)}));
 document.querySelectorAll('[data-go-search]').forEach(b=>b.addEventListener('click',()=>{byId('fq').focus();byId('find').scrollIntoView({behavior:'smooth',block:'start'})}));
 byId('kycalc-copy').addEventListener('click',async()=>{if(!expr){hint.textContent='هنوز نتیجه‌ای وجود ندارد';return}try{await navigator.clipboard.writeText(justEvaluated?lastValue:expr);hint.textContent='نتیجه کپی شد'}catch(e){hint.textContent='کپی در این مرورگر مجاز نیست';}});
 document.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape'){closeCalc();return}if(e.key==='Enter'||e.key==='='){e.preventDefault();press('equals');return}if(e.key==='Backspace'){e.preventDefault();press('back');return}if(e.key==='Delete'){press('clear');return}if(/^[0-9]$/.test(e.key)){press('digit',e.key);return}if(['+','-','*','/'].includes(e.key)){press('op',e.key);return}if(e.key==='.'){press('decimal');return}if(e.key==='%'){press('percent');return}});
 // Improve fallback if the photo source is unavailable; the attribution remains visible.
 const photo=byId('kyv-intro-img');if(photo){photo.addEventListener('error',()=>{if(!photo.dataset.retry){photo.dataset.retry='1';photo.src='https://commons.wikimedia.org/wiki/Special:FilePath/Rowza_Shrine_Hazrat_Ali_Mazar-e_Sharif_Afghanistan......._front.jpg?width=1280';return}photo.style.display='none';byId('kyv-intro-art').classList.add('photo-unavailable');photo.alt='نمایش عکس روضه شریف به اتصال اینترنت نیاز دارد.'})}
 paint();
})();
